def initialize_internal_disposition(apps, schema_editor):
    InventoryItem = apps.get_model("lifecycle", "FactoryReturnInventoryItem")
    UserTask = apps.get_model("workflow", "UserTask")
    WorkItem = apps.get_model("workflow", "WorkItem")

    InventoryItem.objects.filter(
        stock_status__in=("PENDING_DISASSEMBLY", "PENDING_REPAIR")
    ).update(
        production_status="PENDING",
        matching_status="BLOCKED",
    )
    matching_tasks = WorkItem.objects.filter(
        type__in=(
            "FACTORY_RETURN_DISASSEMBLY_MATCHING",
            "FACTORY_RETURN_REPAIR_MATCHING",
        ),
        status="OPEN",
    )
    for workitem in matching_tasks.iterator():
        payload = dict(workitem.payload or {})
        payload.update(
            {
                "blocked_by_production": True,
                "matching_disposition_ready": False,
            }
        )
        workitem.payload = payload
        workitem.title = "等待生产经理提交处置结果"
        workitem.save(update_fields=("payload", "title", "updated_at"))
        UserTask.objects.filter(workitem=workitem).exclude(state="DONE").update(
            need_action=False,
            display_title_snapshot=workitem.title,
        )


